# -*- coding: utf-8 -*-
"""South Africa, CAPS Natural Sciences Grades 7-9 (built with za_sci). UNITS(grade)."""
from za_sci import ZU, S, GM
from au_sci import nq

LL, MM, EC, PE = "Life and Living", "Matter and Materials", "Energy and Change", "Planet Earth and Beyond"


def UNITS(grade):
    return {7: G7, 8: G8, 9: G9}[grade]()


def L(a, b):
    return "<p>%s</p><p>%s</p>" % (a, b)


def U(area, sort, slug, topic, std, title, short, what, kb, ks, a, b, ex, mist, faq, sets, grade, allow=()):
    meta = "Free Grade %d Natural Sciences worksheets (CAPS): %s. 100 questions with answers." % (grade, what)
    return ZU(area, sort, slug, topic, std, title, short, meta, kb, ks, L(a, b), ex, mist, faq, sets, allow)


def cost(R):
    """cost of electricity in rand: power (W or kW) x time x price per kWh"""
    APP = [("kettle", 2000, (0.05, 0.1, 0.15, 0.2)), ("geyser", 3000, (1, 2, 3, 4)), ("microwave", 1000, (0.1, 0.2, 0.25, 0.5)),
           ("television", 100, (2, 3, 4, 5, 6)), ("fridge", 150, (24,)), ("LED bulb", 10, (5, 6, 8, 10, 12)),
           ("iron", 1200, (0.5, 1, 1.5)), ("heater", 2000, (2, 3, 4, 5)), ("stove plate", 1500, (0.5, 1, 1.5, 2)), ("computer", 200, (2, 4, 5, 8))]

    def f():
        name, w, hs = R.choice(APP)
        h = R.choice(hs)
        price = R.choice((2.5, 3, 3.5, 4))
        kwh = w / 1000 * h
        k = R.choice(("kwh", "cost"))
        if k == "kwh":
            return nq("A %d W %s is used for %s h. How much electrical energy does it use, in kWh?" % (w, name, ("%g" % h)), kwh,
                      [w * h, w / 100 * h, w / 1000 / h], " kWh", "E = P × t = %g kW × %g h = <b>%g kWh</b>." % (w / 1000, h, kwh))
        c = kwh * price
        return nq("A %d W %s is used for %s h. Electricity costs R%.2f per kWh. What does this cost?" % (w, name, "%g" % h, price), c,
                  [w * h * price, kwh / price, kwh], "", "Energy = %g kW × %g h = %g kWh; cost = %g × R%.2f = <b>R%.2f</b>." % (w / 1000, h, kwh, kwh, price, c))
    return f


